/* Generated by apps/handbook/build.mjs — do not edit by hand. */
const CATALOG = {"title":"TwistedPear Handbook","version":"0.1.0","parts":[{"id":"part-1-concepts","title":"Part I — Concepts","chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is"},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals"}]},{"id":"part-2-hosts","title":"Part II — The hosts","chapters":[{"id":"difference-matrix","title":"Live difference matrix"}]},{"id":"part-3-sdk","title":"Part III — Developing mini-apps","chapters":[{"id":"sdk-identity","title":"Identity & signing"},{"id":"sdk-presence","title":"Presence"},{"id":"sdk-storage-kv","title":"Key/value storage"},{"id":"sdk-storage-hyperbee","title":"Hyperbee storage"},{"id":"sdk-lxmf","title":"LXMF messaging"},{"id":"sdk-announce","title":"Announce & subscribe"},{"id":"sdk-resource-fetch","title":"Resource fetch"},{"id":"sdk-workspace","title":"Workspace"},{"id":"sdk-share-cas","title":"Content-addressed share"},{"id":"sdk-apps-package","title":"Packaging & preview"},{"id":"sdk-apps-publish","title":"Publish & install"},{"id":"sdk-ai-chat","title":"AI chat"},{"id":"sdk-widget-gallery","title":"Widget gallery"}]},{"id":"part-4-diagnostics","title":"Part IV — Diagnostics","chapters":[{"id":"running-diagnostics","title":"Running diagnostics"}]}],"chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"What TwistedPear is"},{"type":"paragraph","text":"TwistedPear is a peer-to-peer app platform. A **host** on each device is a full Reticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the host only through the SDK."},{"type":"heading","level":2,"text":"Two planes"},{"type":"list","items":["**Control plane** — Reticulum handles identity, announces, links, LXMF, and"]},{"type":"paragraph","text":"off-grid Resource transfer."},{"type":"list","items":["**Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package"]},{"type":"paragraph","text":"syncs when IP connectivity exists."},{"type":"heading","level":2,"text":"Trust model"},{"type":"paragraph","text":"Publisher identity **is** network identity. Packages are Ed25519-signed with the developer's Reticulum key, so discovering an app and trusting its author use the same root."},{"type":"heading","level":2,"text":"This Handbook"},{"type":"paragraph","text":"This document is itself a mini-app. If it installed and rendered on *this* host, you have already exercised packaging, install, sandbox, broker, and the widget renderer. Chapters later add interactive applets that probe live capabilities."}]},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Reticulum fundamentals"},{"type":"paragraph","text":"Reticulum is a cryptography-based networking stack designed for constrained and unreliable links. TwistedPear uses it as the only hard networking constraint."},{"type":"heading","level":2,"text":"Building blocks"},{"type":"list","items":["**Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.","**Announce** — a signed public advertisement that a destination is reachable.","**Link** — an encrypted channel between two destinations.","**Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).","**LXMF** — store-and-forward messaging on top of Reticulum."]},{"type":"heading","level":2,"text":"App-scoped destinations"},{"type":"paragraph","text":"Mini-apps never hold private keys. The host derives an **app destination** from the device identity plus the app id. The Identity chapter shows that derivation live with an applet."}]},{"id":"difference-matrix","title":"Live difference matrix","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Live difference matrix"},{"type":"paragraph","text":"Hosts share one SDK and widget protocol, but platform sandboxes and entitlements shape what is actually available. `host.info()` returns the facts for **this** host — platform id, host / API versions, enabled roles, interface types, and quota snapshot — instead of asserting differences in stale prose."},{"type":"heading","level":2,"text":"Probe"},{"type":"applet","appletId":"host-info"},{"type":"heading","level":2,"text":"How to read differences"},{"type":"paragraph","text":"| Signal | Typical cause | |---|---| | `platform=web` + no `auto`/`ble` | Browser leaf: WebSocket gateway only (LIMITATIONS.md) | | `platform=ios` + missing multicast | Multicast entitlement / Bonjour path | | `transport=false` on phones | Leaf role; desktops default transport + seeder | | Interface listed but offline | Feature present; peer/hardware not connected |"},{"type":"paragraph","text":"Cross-check with presence (`presence.snapshot`) and Part IV diagnostics: run all applets, export a report via `share:cas`, then paste another device's 256t id to diff results side-by-side."}]},{"id":"sdk-identity","title":"Identity & signing","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Identity & signing"},{"type":"paragraph","text":"The `identity` capability grants an app-scoped destination and brokered signing. Private keys never enter the sandbox."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-identity/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet below calls `identity.destinationHash()` on this host and reports pass / fail / not-granted."},{"type":"applet","appletId":"identity-hash"},{"type":"paragraph","text":"Copy the applet source into DevStudio (when available) to experiment further. See also What TwistedPear is."},{"type":"chapter-link","label":"What TwistedPear is","chapterId":"what-is-twistedpear"}]},{"id":"sdk-presence","title":"Presence","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Presence"},{"type":"paragraph","text":"The `presence` capability lets a mini-app read coarse peer and interface state and host metadata (`host.info`) without raw sockets or interface handles."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-presence/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"presence-snapshot"},{"type":"paragraph","text":"See also the live difference matrix (`host.info`)."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"}]},{"id":"sdk-storage-kv","title":"Key/value storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Key/value storage"},{"type":"paragraph","text":"`storage:kv` is a per-app local store with a byte quota enforced by the host."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-kv/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-kv"}]},{"id":"sdk-storage-hyperbee","title":"Hyperbee storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Hyperbee storage"},{"type":"paragraph","text":"`storage:hyperbee` opens a local-only ordered key/value store (Hyperbee) namespaced to the app. Keys stay sorted so list ranges are useful for feeds and indexes."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-hyperbee/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-hyperbee"}]},{"id":"sdk-lxmf","title":"LXMF messaging","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"LXMF messaging"},{"type":"paragraph","text":"`lxmf:send` and `lxmf:receive` give a mini-app a namespaced mailbox. Private keys stay in the host; the app only sees deliveries for its destination."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-lxmf/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"lxmf-roundtrip"},{"type":"paragraph","text":"See also Identity & signing."},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"}]},{"id":"sdk-announce","title":"Announce & subscribe","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Announce & subscribe"},{"type":"paragraph","text":"Announces are how destinations advertise reachability. Mini-apps publish and subscribe in an app namespace through the host broker."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-announce/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"announce-loop"}]},{"id":"sdk-resource-fetch","title":"Resource fetch","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Resource fetch"},{"type":"paragraph","text":"`resource:fetch` asks the host to pull a Resource through its budget rules. The mini-app never sees sockets or peer handles — only bytes (or a typed error)."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-resource-fetch/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"resource-fetch"}]},{"id":"sdk-workspace","title":"Workspace","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Workspace"},{"type":"paragraph","text":"`workspace` is a private per-app project filesystem of relative paths (strings; 256 KiB/file, 4 MiB and 512 files per app). DevStudio and this Handbook use it for sources and applet seeds."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-workspace/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"workspace-rw"}]},{"id":"sdk-share-cas","title":"Content-addressed share","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Content-addressed share"},{"type":"paragraph","text":"`share:cas` stores a bounded string and returns a 94-character 256t id. Paste or scan that id on another device to `share.get` the same bytes — diagnostics reports and DevStudio hand-offs use this path."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-share-cas/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"share-cas"}]},{"id":"sdk-apps-package","title":"Packaging & preview","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Packaging & preview"},{"type":"paragraph","text":"`apps:package` and `apps:preview` are double-gated: the capability grant plus a host-chrome confirmation the mini-app cannot dismiss. Package signs under the device publisher identity; preview runs the project in the single sandboxed dev-preview slot."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-apps-package/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"apps-package-preview"}]},{"id":"sdk-apps-publish","title":"Publish & install","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Publish & install"},{"type":"paragraph","text":"`apps:publish` announces a packaged 256t id under the publisher identity. `apps:install` asks the host to fetch, verify, and review capabilities before anything runs. Both raise a confirmation dialog on every call."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-apps-publish/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"apps-publish-install"}]},{"id":"sdk-ai-chat","title":"AI chat","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"AI chat"},{"type":"paragraph","text":"`ai:chat` sends prompts to the host-configured OpenRouter-compatible endpoint. The host clamps budgets, enforces a model allowlist, and allows one in-flight request per app. The API key never enters the sandbox."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-ai-chat/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Hosts without an AI endpoint report `unavailable`. When configured, the applet below exercises a single round-trip."},{"type":"applet","appletId":"ai-chat"}]},{"id":"sdk-widget-gallery","title":"Widget gallery","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Widget gallery"},{"type":"paragraph","text":"The widget protocol is the cross-platform UI seam. Allowed components: `view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`, `progress`, `divider`, `spacer`, `code-editor`, `qr-code`."},{"type":"paragraph","text":"`code-editor` is content-by-reference (workspace `documentId`); `qr-code` is sized for 94-character 256t ids. The host rejects unknown props, styles, duplicate ids, and oversized trees."},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet submits a tree that includes every component type. After it reports, the Handbook re-renders this chapter with the result card."},{"type":"applet","appletId":"widget-gallery"}]},{"id":"running-diagnostics","title":"Running diagnostics","partId":"part-4-diagnostics","partTitle":"Part IV — Diagnostics","blocks":[{"type":"heading","level":1,"text":"Running diagnostics"},{"type":"paragraph","text":"Each applet reports `{ appletId, status, details, timings }` with first-class `unavailable` and `not-granted` outcomes."},{"type":"heading","level":2,"text":"On this screen"},{"type":"paragraph","text":"From the Handbook **Contents**, use:"},{"type":"list","items":["**Run all diagnostics** — runs every catalog applet inline on this host","**Export report** — packs host info + results into JSON, stores via `share.put`,"]},{"type":"paragraph","text":"shows a 256t id / QR"},{"type":"list","items":["**Compare report** — paste another device's report id to render a status matrix"]},{"type":"paragraph","text":"Open an SDK chapter and tap **Run applet** for a single probe."},{"type":"heading","level":2,"text":"Software-tier probes"},{"type":"list","items":["Host info — `host.info` (`presence`)","App destination hash — `identity`","Presence snapshot — `presence`","KV round-trip — `storage:kv`","Hyperbee round-trip — `storage:hyperbee`","LXMF self-message — `identity`, `lxmf:*`","Announce publish/subscribe — `announce:*`","Resource fetch — `resource:fetch`","Workspace read/write — `workspace`","CAS share — `share:cas`","Package + preview — `apps:package`, `apps:preview`","Publish + install — `apps:publish`, `apps:install`","AI chat — `ai:chat`","Widget gallery — widget protocol"]},{"type":"paragraph","text":"Device-gated probes (BLE peer, RNode, multicast, camera QR) land in Phase D3."}]}],"applets":[{"id":"ai-chat","title":"AI chat (host-mediated)","capabilities":["ai:chat"],"surfaces":["ai.chat"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/ai-chat/main.js"},{"id":"announce-loop","title":"Announce publish/subscribe","capabilities":["announce:publish","announce:subscribe"],"surfaces":["announce.publish","announce.subscribe"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/announce-loop/main.js"},{"id":"apps-package-preview","title":"Package + preview (confirmed)","capabilities":["apps:package","apps:preview","workspace"],"surfaces":["apps.packageProject","apps.preview","apps.stopPreview","workspace.write"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-package-preview/main.js"},{"id":"apps-publish-install","title":"Publish + install (confirmed)","capabilities":["apps:publish","apps:install","apps:package","workspace"],"surfaces":["apps.packageProject","apps.publish","apps.install"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-publish-install/main.js"},{"id":"host-info","title":"Host info probe","capabilities":["presence"],"surfaces":["host.info"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/host-info/main.js"},{"id":"identity-hash","title":"App destination hash","capabilities":["identity"],"surfaces":["identity.destinationHash"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/identity-hash/main.js"},{"id":"lxmf-roundtrip","title":"LXMF self-message","capabilities":["identity","lxmf:send","lxmf:receive"],"surfaces":["identity.destinationHash","lxmf.send","lxmf.receive"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/lxmf-roundtrip/main.js"},{"id":"presence-snapshot","title":"Presence snapshot","capabilities":["presence"],"surfaces":["presence.snapshot"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/presence-snapshot/main.js"},{"id":"resource-fetch","title":"Resource fetch with budget","capabilities":["resource:fetch"],"surfaces":["resource.fetch"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/resource-fetch/main.js"},{"id":"share-cas","title":"CAS share put/get","capabilities":["share:cas"],"surfaces":["share.put","share.get"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/share-cas/main.js"},{"id":"storage-hyperbee","title":"Hyperbee round-trip","capabilities":["storage:hyperbee"],"surfaces":["storage.bee.open","storage.bee.put","storage.bee.get","storage.bee.list","storage.bee.del"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-hyperbee/main.js"},{"id":"storage-kv","title":"KV round-trip","capabilities":["storage:kv"],"surfaces":["storage.kv.get","storage.kv.set","storage.kv.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-kv/main.js"},{"id":"widget-gallery","title":"Widget gallery smoke","capabilities":["workspace"],"surfaces":["ui.render"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/widget-gallery/main.js"},{"id":"workspace-rw","title":"Workspace read/write","capabilities":["workspace"],"surfaces":["workspace.write","workspace.read","workspace.list","workspace.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/workspace-rw/main.js"}],"seeds":[{"path":"applets/ai-chat/applet.json","content":"{\n  \"id\": \"ai-chat\",\n  \"title\": \"AI chat (host-mediated)\",\n  \"capabilities\": [\n    \"ai:chat\"\n  ],\n  \"surfaces\": [\n    \"ai.chat\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/ai-chat/main.js","content":"/**\n * Handbook applet: ai.chat against the host-configured endpoint.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const response = await sdk.ai.chat({\n      messages: [{ role: \"user\", content: \"Reply with the single word: handbook\" }]\n    });\n    if (response === null || typeof response !== \"object\" || response.message === undefined) {\n      report({\n        status: \"fail\",\n        details: `Expected AI response object, got: ${JSON.stringify(response)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const content = response.message?.content;\n    if (typeof content !== \"string\" || content.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"AI response message.content was empty\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `AI replied (${response.model ?? \"unknown model\"}): ${content.slice(0, 80)}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|AI_UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/announce-loop/applet.json","content":"{\n  \"id\": \"announce-loop\",\n  \"title\": \"Announce publish/subscribe\",\n  \"capabilities\": [\n    \"announce:publish\",\n    \"announce:subscribe\"\n  ],\n  \"surfaces\": [\n    \"announce.publish\",\n    \"announce.subscribe\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/announce-loop/main.js","content":"/**\n * Handbook applet: announce.publish then announce.subscribe in a local namespace.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const namespace = \"handbook-probe\";\n  const payload = new TextEncoder().encode(`announce-${started}`);\n  try {\n    await sdk.announce.publish(payload, namespace);\n    const events = await sdk.announce.subscribe(namespace);\n    if (!Array.isArray(events)) {\n      report({\n        status: \"fail\",\n        details: `Expected announce array, got: ${typeof events}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (events.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Subscribe returned no announces after publish\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and observed ${events.length} announce(s) in ${namespace}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-package-preview/applet.json","content":"{\n  \"id\": \"apps-package-preview\",\n  \"title\": \"Package + preview (confirmed)\",\n  \"capabilities\": [\n    \"apps:package\",\n    \"apps:preview\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.preview\",\n    \"apps.stopPreview\",\n    \"workspace.write\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-package-preview/main.js","content":"/**\n * Handbook applet: seed a tiny project, package it, then preview (host confirmation).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-probe-app\";\n  const manifest = {\n    name: \"hb-probe\",\n    version: \"0.0.1\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  try {\n    await sdk.workspace.write(\n      `${project}/app.json`,\n      JSON.stringify({ name: manifest.name, version: manifest.version, entry: manifest.entry, capabilities: manifest.capabilities })\n    );\n    await sdk.workspace.write(\n      `${project}/bundle.js`,\n      `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"probe\" } } });\\n`\n    );\n\n    const packed = await sdk.apps.packageProject(project, manifest);\n    if (packed === null || typeof packed.t256 !== \"string\" || packed.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Expected package with 256t id, got: ${JSON.stringify(packed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const preview = await sdk.apps.preview(project, manifest, [\"identity\"]);\n    if (preview === null || preview.launched !== true) {\n      report({\n        status: \"fail\",\n        details: `Expected preview.launched === true, got: ${JSON.stringify(preview)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.apps.stopPreview();\n\n    report({\n      status: \"pass\",\n      details: `Packaged (${packed.t256.slice(0, 12)}…) and previewed`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-publish-install/applet.json","content":"{\n  \"id\": \"apps-publish-install\",\n  \"title\": \"Publish + install (confirmed)\",\n  \"capabilities\": [\n    \"apps:publish\",\n    \"apps:install\",\n    \"apps:package\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.publish\",\n    \"apps.install\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-publish-install/main.js","content":"/**\n * Handbook applet: package → publish → install (each step host-confirmed).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-distrib-app\";\n  const manifest = {\n    name: \"hb-distrib\",\n    version: \"0.0.1\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  try {\n    await sdk.workspace.write(\n      `${project}/app.json`,\n      JSON.stringify({\n        name: manifest.name,\n        version: manifest.version,\n        entry: manifest.entry,\n        capabilities: manifest.capabilities\n      })\n    );\n    await sdk.workspace.write(\n      `${project}/bundle.js`,\n      `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"distrib\" } } });\\n`\n    );\n\n    const packed = await sdk.apps.packageProject(project, manifest);\n    if (typeof packed?.t256 !== \"string\" || packed.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Package failed: ${JSON.stringify(packed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const published = await sdk.apps.publish(packed.t256);\n    if (published === null || typeof published.t256 !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Publish failed: ${JSON.stringify(published)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const installed = await sdk.apps.install(published.t256);\n    if (installed === null || typeof installed.appId !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Install failed: ${JSON.stringify(installed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and installed ${installed.appId}@${installed.version}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/host-info/applet.json","content":"{\n  \"id\": \"host-info\",\n  \"title\": \"Host info probe\",\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/host-info/main.js","content":"/**\n * Handbook applet: host.info() platform / roles / interfaces / quotas.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    if (sdk.host === undefined || typeof sdk.host.info !== \"function\") {\n      report({\n        status: \"unavailable\",\n        details: \"host.info is not available in this sandbox (upgrade host API).\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const info = await sdk.host.info();\n    if (info === null || typeof info !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a host info object, got: ${String(info)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const platform = typeof info.platform === \"string\" ? info.platform : \"?\";\n    const api = typeof info.hostApiVersion === \"string\" ? info.hostApiVersion : \"?\";\n    const roles = info.roles ?? {};\n    const interfaces = Array.isArray(info.interfaceTypes) ? info.interfaceTypes.join(\",\") : \"\";\n\n    report({\n      status: \"pass\",\n      details: `platform=${platform} api=${api} transport=${roles.transport === true} seeder=${roles.seeder === true} interfaces=[${interfaces}]`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /UNKNOWN_METHOD|not available|upgrade host/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/identity-hash/applet.json","content":"{\n  \"id\": \"identity-hash\",\n  \"title\": \"App destination hash\",\n  \"capabilities\": [\n    \"identity\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/identity-hash/main.js","content":"/**\n * Handbook applet: prove identity.destinationHash() on this host.\n * Export async function run(sdk, report).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const hash = await sdk.identity.destinationHash();\n    if (typeof hash !== \"string\" || hash.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected a non-empty destination hash string, got: ${String(hash)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `destinationHash = ${hash}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted =\n      message.includes(\"CAPABILITY_DENIED\") ||\n      message.includes(\"has not been granted\") ||\n      message.includes(\"Capability\");\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/applet.json","content":"{\n  \"id\": \"lxmf-roundtrip\",\n  \"title\": \"LXMF self-message\",\n  \"capabilities\": [\n    \"identity\",\n    \"lxmf:send\",\n    \"lxmf:receive\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\",\n    \"lxmf.send\",\n    \"lxmf.receive\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/main.js","content":"/**\n * Handbook applet: send an LXMF message to this app (by app id) and read it back.\n * The default host LXMF backend keys inboxes by app id (same as the chat example).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const me = await sdk.identity.destinationHash();\n    const body = `handbook-lxmf-${started}`;\n    // Deliver to this Handbook app's inbox (app id === \"handbook\").\n    await sdk.lxmf.send({ to: \"handbook\", subject: \"handbook-probe\", body });\n    const inbox = await sdk.lxmf.receive();\n    if (!Array.isArray(inbox)) {\n      report({\n        status: \"fail\",\n        details: `Expected inbox array, got: ${typeof inbox}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const hit = inbox.find((message) => message && message.body === body);\n    if (hit === undefined) {\n      report({\n        status: \"fail\",\n        details: `Inbox had ${inbox.length} message(s); self-message not found`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Self-message round-trip (destinationHash=${me})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/presence-snapshot/applet.json","content":"{\n  \"id\": \"presence-snapshot\",\n  \"title\": \"Presence snapshot\",\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/presence-snapshot/main.js","content":"/**\n * Handbook applet: presence.snapshot() on this host.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const snap = await sdk.presence.snapshot();\n    if (snap === null || typeof snap !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a presence snapshot object, got: ${String(snap)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `peers=${snap.peers} interfaces=${snap.onlineInterfaces} preferred=${snap.preferredInterface ?? \"none\"}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/resource-fetch/applet.json","content":"{\n  \"id\": \"resource-fetch\",\n  \"title\": \"Resource fetch with budget\",\n  \"capabilities\": [\n    \"resource:fetch\"\n  ],\n  \"surfaces\": [\n    \"resource.fetch\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/resource-fetch/main.js","content":"/**\n * Handbook applet: resource.fetch under a host budget.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const bytes = await sdk.resource.fetch({\n      resourceId: \"handbook:probe\",\n      budgetBytes: 4096\n    });\n    if (!(bytes instanceof Uint8Array) || bytes.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected non-empty Uint8Array, got: ${typeof bytes}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Fetched ${bytes.length} byte(s) for handbook:probe`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable|not found/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/share-cas/applet.json","content":"{\n  \"id\": \"share-cas\",\n  \"title\": \"CAS share put/get\",\n  \"capabilities\": [\n    \"share:cas\"\n  ],\n  \"surfaces\": [\n    \"share.put\",\n    \"share.get\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/share-cas/main.js","content":"/**\n * Handbook applet: share.put → share.get round-trip.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const content = `handbook-cas-${started}`;\n  try {\n    const put = await sdk.share.put(content);\n    if (put === null || typeof put !== \"object\" || typeof put.t256 !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Expected { t256 }, got: ${JSON.stringify(put)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (put.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Expected 94-char 256t id, got length ${put.t256.length}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const got = await sdk.share.get(put.t256);\n    if (got !== content) {\n      report({\n        status: \"fail\",\n        details: `CAS get mismatch: ${String(got)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `CAS round-trip (${put.t256.slice(0, 12)}…)`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-hyperbee/applet.json","content":"{\n  \"id\": \"storage-hyperbee\",\n  \"title\": \"Hyperbee round-trip\",\n  \"capabilities\": [\n    \"storage:hyperbee\"\n  ],\n  \"surfaces\": [\n    \"storage.bee.open\",\n    \"storage.bee.put\",\n    \"storage.bee.get\",\n    \"storage.bee.list\",\n    \"storage.bee.del\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-hyperbee/main.js","content":"/**\n * Handbook applet: storage.bee open → put → get → list → del.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = `handbook:bee:${started}`;\n  const payload = new TextEncoder().encode(`bee-${started}`);\n  try {\n    await sdk.storage.bee.open();\n    await sdk.storage.bee.put(key, payload);\n    const got = await sdk.storage.bee.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee get returned null after put\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (new TextDecoder().decode(got) !== `bee-${started}`) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee value mismatch\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const listed = await sdk.storage.bee.list({ gte: key, limit: 5 });\n    if (!Array.isArray(listed) || listed.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee list did not include the put key\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.bee.del(key);\n    const after = await sdk.storage.bee.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee value still present after del\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"Hyperbee open → put → get → list → del succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-kv/applet.json","content":"{\n  \"id\": \"storage-kv\",\n  \"title\": \"KV round-trip\",\n  \"capabilities\": [\n    \"storage:kv\"\n  ],\n  \"surfaces\": [\n    \"storage.kv.get\",\n    \"storage.kv.set\",\n    \"storage.kv.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-kv/main.js","content":"/**\n * Handbook applet: storage.kv set → get → delete.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = \"handbook:applet-kv-probe\";\n  const payload = new TextEncoder().encode(`probe-${started}`);\n  try {\n    await sdk.storage.kv.set(key, payload);\n    const got = await sdk.storage.kv.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"KV get returned null after set\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const text = new TextDecoder().decode(got);\n    if (text !== `probe-${started}`) {\n      report({\n        status: \"fail\",\n        details: `KV value mismatch: ${text}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.kv.delete(key);\n    const after = await sdk.storage.kv.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"KV value still present after delete\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"KV set → get → delete succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/widget-gallery/applet.json","content":"{\n  \"id\": \"widget-gallery\",\n  \"title\": \"Widget gallery smoke\",\n  \"capabilities\": [\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"ui.render\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/widget-gallery/main.js","content":"/**\n * Handbook applet: validate that every widget component type can appear in a tree.\n * Inline mode shares the Handbook sandbox; the runtime re-renders the chapter after.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    await sdk.workspace.write(\"probes/widget-gallery.txt\", \"gallery-seed\");\n\n    await sdk.ui.render({\n      root: {\n        id: \"gallery-root\",\n        type: \"scroll\",\n        style: { padding: 8, gap: 6 },\n        children: [\n          {\n            id: \"g-view\",\n            type: \"view\",\n            style: { gap: 4 },\n            children: [\n              { id: \"g-text\", type: \"text\", props: { value: \"Widget gallery\" } },\n              { id: \"g-image\", type: \"image\", props: { asset: \"handbook-icon\", alt: \"icon\" } },\n              { id: \"g-button\", type: \"button\", props: { label: \"Ok\", event: \"hb.gallery.noop\" } },\n              {\n                id: \"g-input\",\n                type: \"text-input\",\n                props: { value: \"\", placeholder: \"type\", event: \"hb.gallery.input\" }\n              },\n              { id: \"g-switch\", type: \"switch\", props: { value: false, event: \"hb.gallery.switch\" } },\n              { id: \"g-progress\", type: \"progress\", props: { value: 0.4 } },\n              { id: \"g-divider\", type: \"divider\" },\n              { id: \"g-spacer\", type: \"spacer\", props: { size: 8 } },\n              { id: \"g-list\", type: \"list\", props: { items: [\"item-a\", \"item-b\"] } },\n              {\n                id: \"g-editor\",\n                type: \"code-editor\",\n                props: { documentId: \"probes/widget-gallery.txt\", language: \"text\", readOnly: true }\n              },\n              {\n                id: \"g-qr\",\n                type: \"qr-code\",\n                props: { value: \"handbook-gallery\", caption: \"gallery\", size: 96 }\n              }\n            ]\n          }\n        ]\n      }\n    });\n\n    report({\n      status: \"pass\",\n      details:\n        \"Rendered scroll/view/text/image/button/text-input/switch/progress/divider/spacer/list/code-editor/qr-code\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/workspace-rw/applet.json","content":"{\n  \"id\": \"workspace-rw\",\n  \"title\": \"Workspace read/write\",\n  \"capabilities\": [\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"workspace.write\",\n    \"workspace.read\",\n    \"workspace.list\",\n    \"workspace.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/workspace-rw/main.js","content":"/**\n * Handbook applet: workspace write → read → list → remove.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const path = `probes/workspace-${started}.txt`;\n  const body = `workspace-probe-${started}`;\n  try {\n    await sdk.workspace.write(path, body);\n    const read = await sdk.workspace.read(path);\n    if (read !== body) {\n      report({\n        status: \"fail\",\n        details: `Workspace read mismatch: ${String(read)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const listed = await sdk.workspace.list(\"probes/\");\n    if (!Array.isArray(listed) || !listed.some((entry) => entry.path === path || entry === path)) {\n      const paths = Array.isArray(listed)\n        ? listed.map((entry) => (typeof entry === \"string\" ? entry : entry.path)).join(\", \")\n        : String(listed);\n      report({\n        status: \"fail\",\n        details: `Workspace list missing ${path}; got: ${paths}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.workspace.remove(path);\n    report({\n      status: \"pass\",\n      details: `Workspace write → read → list → remove for ${path}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"chapters/difference-matrix/source.md","content":"# Live difference matrix\n\nHosts share one SDK and widget protocol, but platform sandboxes and entitlements\nshape what is actually available. `host.info()` returns the facts for **this**\nhost — platform id, host / API versions, enabled roles, interface types, and\nquota snapshot — instead of asserting differences in stale prose.\n\n## Probe\n\n{{applet:host-info}}\n\n## How to read differences\n\n| Signal | Typical cause |\n|---|---|\n| `platform=web` + no `auto`/`ble` | Browser leaf: WebSocket gateway only ([LIMITATIONS.md](../../../LIMITATIONS.md)) |\n| `platform=ios` + missing multicast | Multicast entitlement / Bonjour path |\n| `transport=false` on phones | Leaf role; desktops default transport + seeder |\n| Interface listed but offline | Feature present; peer/hardware not connected |\n\nCross-check with presence (`presence.snapshot`) and Part IV diagnostics: run all\napplets, export a report via `share:cas`, then paste another device's 256t id to\ndiff results side-by-side.\n"},{"path":"chapters/reticulum-fundamentals/source.md","content":"# Reticulum fundamentals\n\nReticulum is a cryptography-based networking stack designed for constrained and\nunreliable links. TwistedPear uses it as the only hard networking constraint.\n\n## Building blocks\n\n- **Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.\n- **Announce** — a signed public advertisement that a destination is reachable.\n- **Link** — an encrypted channel between two destinations.\n- **Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).\n- **LXMF** — store-and-forward messaging on top of Reticulum.\n\n## App-scoped destinations\n\nMini-apps never hold private keys. The host derives an **app destination** from\nthe device identity plus the app id. The Identity chapter shows that derivation\nlive with an applet.\n"},{"path":"chapters/running-diagnostics/source.md","content":"# Running diagnostics\n\nEach applet reports `{ appletId, status, details, timings }` with first-class\n`unavailable` and `not-granted` outcomes.\n\n## On this screen\n\nFrom the Handbook **Contents**, use:\n\n- **Run all diagnostics** — runs every catalog applet inline on this host\n- **Export report** — packs host info + results into JSON, stores via `share.put`,\n  shows a 256t id / QR\n- **Compare report** — paste another device's report id to render a status matrix\n\nOpen an SDK chapter and tap **Run applet** for a single probe.\n\n## Software-tier probes\n\n- Host info — `host.info` (`presence`)\n- App destination hash — `identity`\n- Presence snapshot — `presence`\n- KV round-trip — `storage:kv`\n- Hyperbee round-trip — `storage:hyperbee`\n- LXMF self-message — `identity`, `lxmf:*`\n- Announce publish/subscribe — `announce:*`\n- Resource fetch — `resource:fetch`\n- Workspace read/write — `workspace`\n- CAS share — `share:cas`\n- Package + preview — `apps:package`, `apps:preview`\n- Publish + install — `apps:publish`, `apps:install`\n- AI chat — `ai:chat`\n- Widget gallery — widget protocol\n\nDevice-gated probes (BLE peer, RNode, multicast, camera QR) land in Phase D3.\n"},{"path":"chapters/sdk-ai-chat/sample-0.js","content":"import { ai } from \"@twistedpear/miniapp-sdk\";\n\nconst response = await ai.chat({\n  messages: [{ role: \"user\", content: \"hello\" }]\n});\n"},{"path":"chapters/sdk-ai-chat/source.md","content":"# AI chat\n\n`ai:chat` sends prompts to the host-configured OpenRouter-compatible endpoint.\nThe host clamps budgets, enforces a model allowlist, and allows one in-flight\nrequest per app. The API key never enters the sandbox.\n\n## API\n\n```javascript\nimport { ai } from \"@twistedpear/miniapp-sdk\";\n\nconst response = await ai.chat({\n  messages: [{ role: \"user\", content: \"hello\" }]\n});\n```\n\n## Live probe\n\nHosts without an AI endpoint report `unavailable`. When configured, the applet\nbelow exercises a single round-trip.\n\n{{applet:ai-chat}}\n"},{"path":"chapters/sdk-announce/sample-0.js","content":"import { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish(appDataBytes, \"my-namespace\");\nconst events = await announce.subscribe(\"my-namespace\");\n"},{"path":"chapters/sdk-announce/source.md","content":"# Announce & subscribe\n\nAnnounces are how destinations advertise reachability. Mini-apps publish and\nsubscribe in an app namespace through the host broker.\n\n## API\n\n```javascript\nimport { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish(appDataBytes, \"my-namespace\");\nconst events = await announce.subscribe(\"my-namespace\");\n```\n\n## Live probe\n\n{{applet:announce-loop}}\n"},{"path":"chapters/sdk-apps-package/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nconst { launched } = await apps.preview(\"my-app\", manifest, grants);\nawait apps.stopPreview();\n"},{"path":"chapters/sdk-apps-package/source.md","content":"# Packaging & preview\n\n`apps:package` and `apps:preview` are double-gated: the capability grant plus a\nhost-chrome confirmation the mini-app cannot dismiss. Package signs under the\ndevice publisher identity; preview runs the project in the single sandboxed\ndev-preview slot.\n\n## API\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nconst { launched } = await apps.preview(\"my-app\", manifest, grants);\nawait apps.stopPreview();\n```\n\n## Live probe\n\n{{applet:apps-package-preview}}\n"},{"path":"chapters/sdk-apps-publish/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nawait apps.publish(t256);\nconst installed = await apps.install(t256);\n"},{"path":"chapters/sdk-apps-publish/source.md","content":"# Publish & install\n\n`apps:publish` announces a packaged 256t id under the publisher identity.\n`apps:install` asks the host to fetch, verify, and review capabilities before\nanything runs. Both raise a confirmation dialog on every call.\n\n## API\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nawait apps.publish(t256);\nconst installed = await apps.install(t256);\n```\n\n## Live probe\n\n{{applet:apps-publish-install}}\n"},{"path":"chapters/sdk-identity/sample-0.js","content":"import { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n"},{"path":"chapters/sdk-identity/source.md","content":"# Identity & signing\n\nThe `identity` capability grants an app-scoped destination and brokered signing.\nPrivate keys never enter the sandbox.\n\n## API\n\n```javascript\nimport { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n```\n\n## Live probe\n\nThe applet below calls `identity.destinationHash()` on this host and reports\npass / fail / not-granted.\n\n{{applet:identity-hash}}\n\nCopy the applet source into DevStudio (when available) to experiment further.\nSee also [What TwistedPear is](chapter:what-is-twistedpear).\n"},{"path":"chapters/sdk-lxmf/sample-0.js","content":"import { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n"},{"path":"chapters/sdk-lxmf/source.md","content":"# LXMF messaging\n\n`lxmf:send` and `lxmf:receive` give a mini-app a namespaced mailbox. Private\nkeys stay in the host; the app only sees deliveries for its destination.\n\n## API\n\n```javascript\nimport { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n```\n\n## Live probe\n\n{{applet:lxmf-roundtrip}}\n\nSee also [Identity & signing](chapter:sdk-identity).\n"},{"path":"chapters/sdk-presence/sample-0.js","content":"import { presence, host } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { onlineInterfaces, preferredInterface, peers }\n\nconst info = await host.info();\n// { platform, hostVersion, hostApiVersion, roles, interfaceTypes, quotas }\n"},{"path":"chapters/sdk-presence/source.md","content":"# Presence\n\nThe `presence` capability lets a mini-app read coarse peer and interface state\nand host metadata (`host.info`) without raw sockets or interface handles.\n\n## API\n\n```javascript\nimport { presence, host } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { onlineInterfaces, preferredInterface, peers }\n\nconst info = await host.info();\n// { platform, hostVersion, hostApiVersion, roles, interfaceTypes, quotas }\n```\n\n## Live probe\n\n{{applet:presence-snapshot}}\n\nSee also the [live difference matrix](chapter:difference-matrix) (`host.info`).\n"},{"path":"chapters/sdk-resource-fetch/sample-0.js","content":"import { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n"},{"path":"chapters/sdk-resource-fetch/source.md","content":"# Resource fetch\n\n`resource:fetch` asks the host to pull a Resource through its budget rules.\nThe mini-app never sees sockets or peer handles — only bytes (or a typed error).\n\n## API\n\n```javascript\nimport { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n```\n\n## Live probe\n\n{{applet:resource-fetch}}\n"},{"path":"chapters/sdk-share-cas/sample-0.js","content":"import { share } from \"@twistedpear/miniapp-sdk\";\n\nconst { t256, size } = await share.put(\"hello\");\nconst again = await share.get(t256);\n"},{"path":"chapters/sdk-share-cas/source.md","content":"# Content-addressed share\n\n`share:cas` stores a bounded string and returns a 94-character 256t id.\nPaste or scan that id on another device to `share.get` the same bytes —\ndiagnostics reports and DevStudio hand-offs use this path.\n\n## API\n\n```javascript\nimport { share } from \"@twistedpear/miniapp-sdk\";\n\nconst { t256, size } = await share.put(\"hello\");\nconst again = await share.get(t256);\n```\n\n## Live probe\n\n{{applet:share-cas}}\n"},{"path":"chapters/sdk-storage-hyperbee/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.bee.open();\nawait storage.bee.put(\"post:1\", bytes);\nconst value = await storage.bee.get(\"post:1\");\nconst entries = await storage.bee.list({ limit: 10 });\nawait storage.bee.del(\"post:1\");\n"},{"path":"chapters/sdk-storage-hyperbee/source.md","content":"# Hyperbee storage\n\n`storage:hyperbee` opens a local-only ordered key/value store (Hyperbee)\nnamespaced to the app. Keys stay sorted so list ranges are useful for feeds\nand indexes.\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.bee.open();\nawait storage.bee.put(\"post:1\", bytes);\nconst value = await storage.bee.get(\"post:1\");\nconst entries = await storage.bee.list({ limit: 10 });\nawait storage.bee.del(\"post:1\");\n```\n\n## Live probe\n\n{{applet:storage-hyperbee}}\n"},{"path":"chapters/sdk-storage-kv/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n"},{"path":"chapters/sdk-storage-kv/source.md","content":"# Key/value storage\n\n`storage:kv` is a per-app local store with a byte quota enforced by the host.\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n```\n\n## Live probe\n\n{{applet:storage-kv}}\n"},{"path":"chapters/sdk-widget-gallery/source.md","content":"# Widget gallery\n\nThe widget protocol is the cross-platform UI seam. Allowed components:\n`view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`,\n`progress`, `divider`, `spacer`, `code-editor`, `qr-code`.\n\n`code-editor` is content-by-reference (workspace `documentId`); `qr-code` is\nsized for 94-character 256t ids. The host rejects unknown props, styles,\nduplicate ids, and oversized trees.\n\n## Live probe\n\nThe applet submits a tree that includes every component type. After it reports,\nthe Handbook re-renders this chapter with the result card.\n\n{{applet:widget-gallery}}\n"},{"path":"chapters/sdk-workspace/sample-0.js","content":"import { workspace } from \"@twistedpear/miniapp-sdk\";\n\nawait workspace.write(\"src/main.js\", source);\nconst text = await workspace.read(\"src/main.js\");\nconst files = await workspace.list(\"src/\");\nawait workspace.remove(\"src/main.js\");\n"},{"path":"chapters/sdk-workspace/source.md","content":"# Workspace\n\n`workspace` is a private per-app project filesystem of relative paths\n(strings; 256 KiB/file, 4 MiB and 512 files per app). DevStudio and this\nHandbook use it for sources and applet seeds.\n\n## API\n\n```javascript\nimport { workspace } from \"@twistedpear/miniapp-sdk\";\n\nawait workspace.write(\"src/main.js\", source);\nconst text = await workspace.read(\"src/main.js\");\nconst files = await workspace.list(\"src/\");\nawait workspace.remove(\"src/main.js\");\n```\n\n## Live probe\n\n{{applet:workspace-rw}}\n"},{"path":"chapters/what-is-twistedpear/source.md","content":"# What TwistedPear is\n\nTwistedPear is a peer-to-peer app platform. A **host** on each device is a full\nReticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the\nhost only through the SDK.\n\n## Two planes\n\n- **Control plane** — Reticulum handles identity, announces, links, LXMF, and\n  off-grid Resource transfer.\n- **Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package\n  syncs when IP connectivity exists.\n\n## Trust model\n\nPublisher identity **is** network identity. Packages are Ed25519-signed with the\ndeveloper's Reticulum key, so discovering an app and trusting its author use the\nsame root.\n\n## This Handbook\n\nThis document is itself a mini-app. If it installed and rendered on *this* host,\nyou have already exercised packaging, install, sandbox, broker, and the widget\nrenderer. Chapters later add interactive applets that probe live capabilities.\n"}]};
import {
  ai,
  apps,
  announce,
  host,
  identity,
  lxmf,
  presence,
  resource,
  share,
  storage,
  ui,
  workspace
} from "@twistedpear/miniapp-sdk";

// Handbook runtime — TOC, chapter renderer, inline applet runner, diagnostics.
// CATALOG is injected by build.mjs immediately above this file in bundle.js.

const POSITION_KEY = "handbook:position";
const SEEDED_KEY = "handbook:seeded";
const SEED_VERSION_KEY = "handbook:seed-version";
const LAST_REPORT_KEY = "handbook:last-report";
const REPORT_SCHEMA_VERSION = 1;

/** @type {"toc" | "chapter" | "diagnostics"} */
let view = "toc";
/** @type {string | null} */
let chapterId = null;
/** @type {Record<string, { status: string, details: string, timings?: { ms: number } }>} */
let appletResults = {};
/** @type {string | null} */
let statusLine = null;
/** @type {boolean} */
let seeding = false;
/** @type {boolean} */
let runningAll = false;
/** @type {{ reportId: string | null, generatedAt: string | null, json: string | null }} */
let exportState = { reportId: null, generatedAt: null, json: null };
/** @type {string} */
let compareInput = "";
/** @type {{ local: object | null, remote: object | null, rows: Array<object>, error: string | null }} */
let compareState = { local: null, remote: null, rows: [], error: null };

function makeSdk() {
  return {
    identity,
    presence,
    host,
    announce,
    lxmf,
    storage,
    resource,
    workspace,
    ui,
    share,
    apps,
    ai
  };
}

function findChapter(id) {
  return CATALOG.chapters.find((chapter) => chapter.id === id) ?? null;
}

function findApplet(id) {
  return CATALOG.applets.find((applet) => applet.id === id) ?? null;
}

async function kvGetText(key) {
  const bytes = await storage.kv.get(key);
  if (bytes === null) {
    return null;
  }
  return new TextDecoder().decode(bytes);
}

async function kvSetText(key, value) {
  await storage.kv.set(key, new TextEncoder().encode(value));
}

async function ensureSeeds() {
  const version = await kvGetText(SEED_VERSION_KEY);
  const seeded = await kvGetText(SEEDED_KEY);
  if (seeded === "1" && version === CATALOG.version) {
    return;
  }

  seeding = true;
  try {
    for (const seed of CATALOG.seeds) {
      await workspace.write(seed.path, seed.content);
    }
    await kvSetText(SEEDED_KEY, "1");
    await kvSetText(SEED_VERSION_KEY, CATALOG.version);
  } finally {
    seeding = false;
  }
}

function widgetButton(id, label, event) {
  return { id, type: "button", props: { label, event } };
}

function textNode(id, value, style) {
  const node = { id, type: "text", props: { value } };
  if (style !== undefined) {
    node.style = style;
  }
  return node;
}

function headingStyle(level) {
  if (level === 1) {
    return { fontSize: 24, fontWeight: "bold" };
  }
  if (level === 2) {
    return { fontSize: 20, fontWeight: "bold" };
  }
  return { fontSize: 16, fontWeight: "bold" };
}

function resultCard(appletId, result) {
  if (result === undefined) {
    return textNode(`result-${appletId}-empty`, "Not run yet.");
  }

  const label = result.status.toUpperCase();
  const timing =
    result.timings && typeof result.timings.ms === "number" ? ` (${result.timings.ms} ms)` : "";
  return textNode(
    `result-${appletId}`,
    `${label}${timing}\n${result.details}`
  );
}

function explainStatus(status) {
  if (status === "not-granted") {
    return "This capability was withheld for this app. Grant it at install to run the probe.";
  }
  if (status === "unavailable") {
    return "This host does not implement the feature; that is an expected platform difference.";
  }
  if (status === "skipped") {
    return "Skipped.";
  }
  return null;
}

function renderAppletBlock(appletId, children) {
  const applet = findApplet(appletId);
  if (applet === null) {
    children.push(textNode(`missing-${appletId}`, `Missing applet: ${appletId}`));
    return;
  }

  children.push({ id: `applet-sep-${appletId}`, type: "divider" });
  children.push(
    textNode(`applet-title-${appletId}`, `Applet: ${applet.title}`, {
      fontSize: 16,
      fontWeight: "bold"
    })
  );
  children.push(
    textNode(
      `applet-caps-${appletId}`,
      `Requires: ${applet.capabilities.join(", ")}`
    )
  );
  children.push({
    id: `applet-src-${appletId}`,
    type: "code-editor",
    props: {
      documentId: `applets/${appletId}/main.js`,
      language: "javascript",
      readOnly: true
    }
  });
  children.push(
    widgetButton(`applet-run-${appletId}`, "Run applet", "hb.runapplet")
  );

  const result = appletResults[appletId];
  children.push(resultCard(appletId, result));
  if (result !== undefined) {
    const explanation = explainStatus(result.status);
    if (explanation !== null) {
      children.push(textNode(`applet-explain-${appletId}`, explanation));
    }
  }
}

function renderChapterBlocks(chapter, children) {
  let blockIndex = 0;
  for (const block of chapter.blocks) {
    const bid = `${chapter.id}-b${blockIndex++}`;
    if (block.type === "heading") {
      children.push(textNode(bid, block.text, headingStyle(block.level)));
      continue;
    }
    if (block.type === "paragraph") {
      children.push(textNode(bid, block.text));
      continue;
    }
    if (block.type === "list") {
      for (let i = 0; i < block.items.length; i += 1) {
        children.push(textNode(`${bid}-i${i}`, `• ${block.items[i]}`));
      }
      continue;
    }
    if (block.type === "code") {
      children.push({
        id: bid,
        type: "code-editor",
        props: {
          documentId: block.documentId,
          language: block.language,
          readOnly: true
        }
      });
      continue;
    }
    if (block.type === "chapter-link") {
      children.push(
        widgetButton(`link-${block.chapterId}-${bid}`, `→ ${block.label}`, "hb.openchapter")
      );
      continue;
    }
    if (block.type === "applet") {
      renderAppletBlock(block.appletId, children);
    }
  }
}

async function fetchHostInfoSafe() {
  try {
    return await host.info();
  } catch (error) {
    return {
      platform: "unknown",
      hostVersion: "unknown",
      hostApiVersion: "unknown",
      roles: { transport: false, seeder: false, propagation: false },
      interfaceTypes: [],
      quotas: {
        kvQuotaBytes: null,
        seedStorageUsedBytes: null,
        seedStorageQuotaBytes: null,
        memoryBytes: null
      },
      error: error instanceof Error ? error.message : String(error)
    };
  }
}

function buildReportDocument(hostInfo) {
  const results = CATALOG.applets.map((applet) => {
    const result = appletResults[applet.id];
    if (result === undefined) {
      return {
        appletId: applet.id,
        status: "skipped",
        details: "Not run",
        timings: { ms: 0 }
      };
    }
    return {
      appletId: applet.id,
      status: result.status,
      details: result.details,
      timings: result.timings ?? { ms: 0 }
    };
  });

  return {
    schemaVersion: REPORT_SCHEMA_VERSION,
    handbookVersion: CATALOG.version,
    generatedAt: new Date().toISOString(),
    host: hostInfo,
    results
  };
}

function diffReports(localReport, remoteReport) {
  const remoteById = new Map(
    (remoteReport.results ?? []).map((row) => [row.appletId, row])
  );
  const rows = [];
  for (const local of localReport.results ?? []) {
    const remote = remoteById.get(local.appletId);
    rows.push({
      appletId: local.appletId,
      local: local.status,
      remote: remote?.status ?? "missing",
      same: remote !== undefined && remote.status === local.status
    });
  }
  return rows;
}

function renderDiagnostics(children) {
  children.push(widgetButton("back-toc-diag", "← Contents", "hb.toc"));
  children.push({ id: "diag-sep", type: "divider" });
  children.push(textNode("diag-title", "Diagnostics", { fontSize: 20, fontWeight: "bold" }));
  children.push(
    textNode(
      "diag-blurb",
      "Run every applet on this host, export a shareable report, or paste another report’s 256t id to compare."
    )
  );

  children.push(
    widgetButton(
      "diag-run-all",
      runningAll ? "Running all…" : "Run all diagnostics",
      "hb.runall"
    )
  );

  const counts = { pass: 0, fail: 0, unavailable: 0, "not-granted": 0, skipped: 0 };
  for (const applet of CATALOG.applets) {
    const result = appletResults[applet.id];
    const status = result?.status ?? "skipped";
    if (counts[status] !== undefined) {
      counts[status] += 1;
    }
    children.push(
      textNode(
        `diag-row-${applet.id}`,
        `${applet.id}: ${(result?.status ?? "skipped").toUpperCase()}`
      )
    );
  }
  children.push(
    textNode(
      "diag-summary",
      `Summary — pass ${counts.pass}, fail ${counts.fail}, unavailable ${counts.unavailable}, not-granted ${counts["not-granted"]}, skipped ${counts.skipped}`
    )
  );

  children.push({ id: "diag-export-sep", type: "divider" });
  children.push(widgetButton("diag-export", "Export report (share.put)", "hb.export"));
  if (exportState.reportId !== null) {
    children.push(
      textNode(
        "diag-export-meta",
        `Exported ${exportState.generatedAt ?? ""}\n${exportState.reportId}`
      )
    );
    children.push({
      id: "diag-export-qr",
      type: "qr-code",
      props: {
        value: exportState.reportId,
        caption: "Scan or copy report 256t id"
      }
    });
  }

  children.push({ id: "diag-compare-sep", type: "divider" });
  children.push(textNode("diag-compare-label", "Compare with remote report id:"));
  children.push({
    id: "diag-compare-input",
    type: "text-input",
    props: {
      value: compareInput,
      placeholder: "Paste 256t id",
      event: "hb.compare.input"
    }
  });
  children.push(widgetButton("diag-compare", "Compare report", "hb.compare"));

  if (compareState.error !== null) {
    children.push(textNode("diag-compare-error", compareState.error));
  }
  if (compareState.rows.length > 0) {
    const localPlat = compareState.local?.host?.platform ?? "?";
    const remotePlat = compareState.remote?.host?.platform ?? "?";
    children.push(
      textNode(
        "diag-compare-hosts",
        `Local host: ${localPlat}  ·  Remote host: ${remotePlat}`
      )
    );
    for (const row of compareState.rows) {
      const mark = row.same ? "=" : "≠";
      children.push(
        textNode(
          `diag-diff-${row.appletId}`,
          `${mark} ${row.appletId}: ${row.local} / ${row.remote}`
        )
      );
    }
  }
}

async function render() {
  const children = [
    textNode("brand", CATALOG.title, { fontSize: 24, fontWeight: "bold" })
  ];

  if (statusLine !== null) {
    children.push(textNode("status", statusLine));
  }

  if (seeding) {
    children.push(textNode("seeding", "Seeding documentation workspace…"));
  }

  if (view === "toc") {
    children.push(textNode("toc-heading", "Contents", { fontSize: 20, fontWeight: "bold" }));
    children.push(
      textNode(
        "toc-blurb",
        "Interactive diagnostic documentation. Open a chapter, then run embedded applets on this host."
      )
    );
    children.push(widgetButton("open-diag", "Diagnostics · run all / export / compare", "hb.diagnostics"));

    for (const part of CATALOG.parts) {
      children.push({ id: `part-sep-${part.id}`, type: "divider" });
      children.push(textNode(`part-${part.id}`, part.title, { fontSize: 16, fontWeight: "bold" }));
      for (const chapter of part.chapters) {
        const marker = chapterId === chapter.id ? "▶ " : "";
        children.push(
          widgetButton(`ch-${chapter.id}`, `${marker}${chapter.title}`, "hb.openchapter")
        );
      }
    }
  } else if (view === "diagnostics") {
    renderDiagnostics(children);
  } else if (view === "chapter") {
    const chapter = findChapter(chapterId);
    children.push(widgetButton("back-toc", "← Contents", "hb.toc"));
    children.push({ id: "chapter-sep", type: "divider" });

    if (chapter === null) {
      children.push(textNode("missing-chapter", `Chapter not found: ${chapterId}`));
    } else {
      children.push(
        textNode("chapter-part", chapter.partTitle, { fontSize: 12, fontWeight: "medium" })
      );
      children.push(
        textNode("chapter-title", chapter.title, { fontSize: 20, fontWeight: "bold" })
      );
      renderChapterBlocks(chapter, children);
    }
  }

  await ui.render({
    root: {
      id: "root",
      type: "scroll",
      style: { padding: 16, gap: 8 },
      children: [
        {
          id: "inner",
          type: "view",
          style: { gap: 8 },
          children
        }
      ]
    }
  });
}

async function openChapter(id) {
  if (findChapter(id) === null) {
    statusLine = `Unknown chapter: ${id}`;
    await render();
    return;
  }

  chapterId = id;
  view = "chapter";
  statusLine = null;
  await kvSetText(POSITION_KEY, id);
  await render();
}

async function openToc() {
  view = "toc";
  statusLine = null;
  await render();
}

async function openDiagnostics() {
  view = "diagnostics";
  statusLine = null;
  await render();
}

function stripAppletExports(source) {
  return source
    .replace(/export\s+async\s+function\s+run\s*/, "async function run ")
    .replace(/export\s+\{[^}]+\}\s*;?/g, "");
}

/**
 * Load applet `run(sdk, report)`. Prefer AsyncFunction (Node sandbox). Fall back
 * to blob-URL import when CSP blocks eval (browser iframe worker has no
 * unsafe-eval).
 */
async function loadAppletRunner(source) {
  const body = stripAppletExports(source);
  try {
    const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
    // Probe — some CSPs allow constructing Function but reject calling it.
    const probe = new AsyncFunction("return 1");
    await probe();
    return new AsyncFunction("sdk", "report", `${body}\nawait run(sdk, report);`);
  } catch {
    const moduleSource = `${body}\nexport async function __handbookRun(sdk, report) {\n  await run(sdk, report);\n}\n`;
    const moduleUrl = URL.createObjectURL(new Blob([moduleSource], { type: "text/javascript" }));
    try {
      const mod = await import(moduleUrl);
      if (typeof mod.__handbookRun !== "function") {
        throw new Error("Applet module did not export __handbookRun");
      }
      return (sdk, report) => mod.__handbookRun(sdk, report);
    } finally {
      URL.revokeObjectURL(moduleUrl);
    }
  }
}

async function runAppletInline(appletId, options = {}) {
  const { quiet = false } = options;
  const applet = findApplet(appletId);
  if (applet === null) {
    if (!quiet) {
      statusLine = `Unknown applet: ${appletId}`;
      await render();
    }
    return null;
  }

  if (!quiet) {
    statusLine = `Running ${applet.title}…`;
    await render();
  }

  let source;
  try {
    source = await workspace.read(`applets/${appletId}/main.js`);
  } catch {
    source = CATALOG.seeds.find((seed) => seed.path === `applets/${appletId}/main.js`)?.content;
  }

  if (typeof source !== "string" || source.length === 0) {
    const failed = {
      status: "fail",
      details: "Applet source not found in workspace seeds."
    };
    appletResults[appletId] = failed;
    if (!quiet) {
      statusLine = null;
      await render();
    }
    return { appletId, ...failed };
  }

  const started = Date.now();
  /** @type {{ status: string, details: string, timings?: { ms: number } } | null} */
  let reported = null;
  const report = (result) => {
    reported = {
      status: result.status,
      details: result.details,
      timings: result.timings ?? { ms: Date.now() - started }
    };
  };

  try {
    const runner = await loadAppletRunner(source);
    await runner(makeSdk(), report);
    if (reported === null) {
      reported = {
        status: "fail",
        details: "Applet finished without calling report().",
        timings: { ms: Date.now() - started }
      };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted =
      /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    reported = {
      status: notGranted ? "not-granted" : "fail",
      details: message,
      timings: { ms: Date.now() - started }
    };
  }

  appletResults[appletId] = reported;
  if (!quiet) {
    statusLine = `${applet.title}: ${reported.status}`;
    await render();
  }
  return { appletId, ...reported };
}

async function runAllDiagnostics() {
  if (runningAll) {
    return;
  }
  runningAll = true;
  statusLine = "Running all diagnostics…";
  view = "diagnostics";
  await render();

  try {
    for (const applet of CATALOG.applets) {
      statusLine = `Running ${applet.title}…`;
      await render();
      await runAppletInline(applet.id, { quiet: true });
      // Restore Handbook chrome after applets that call ui.render (e.g. widget gallery).
      statusLine = `Finished ${applet.title}: ${appletResults[applet.id]?.status ?? "?"}`;
      await render();
    }
    statusLine = `All diagnostics finished (${CATALOG.applets.length} applets)`;
  } finally {
    runningAll = false;
    await render();
  }
}

async function exportReport() {
  statusLine = "Building diagnostic report…";
  await render();

  const hostInfo = await fetchHostInfoSafe();
  const document = buildReportDocument(hostInfo);
  const json = JSON.stringify(document);

  try {
    const put = await share.put(json);
    exportState = {
      reportId: put.t256,
      generatedAt: document.generatedAt,
      json
    };
    await kvSetText(LAST_REPORT_KEY, json);
    compareState = { ...compareState, local: document };
    statusLine = `Report exported (${put.t256.slice(0, 12)}…)`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    exportState = { reportId: null, generatedAt: document.generatedAt, json };
    await kvSetText(LAST_REPORT_KEY, json);
    compareState = { ...compareState, local: document };
    statusLine = `Report built locally but share.put failed: ${message}`;
  }

  view = "diagnostics";
  await render();
}

async function compareReport() {
  const t256 = compareInput.trim();
  if (t256.length === 0) {
    compareState = { local: compareState.local, remote: null, rows: [], error: "Paste a report 256t id first." };
    await render();
    return;
  }

  statusLine = "Fetching remote report…";
  await render();

  let local = compareState.local;
  if (local === null) {
    const cached = await kvGetText(LAST_REPORT_KEY);
    if (cached !== null) {
      try {
        local = JSON.parse(cached);
      } catch {
        local = null;
      }
    }
  }
  if (local === null) {
    const hostInfo = await fetchHostInfoSafe();
    local = buildReportDocument(hostInfo);
  }

  try {
    const remoteJson = await share.get(t256);
    if (typeof remoteJson !== "string" || remoteJson.length === 0) {
      compareState = {
        local,
        remote: null,
        rows: [],
        error: "Remote report not found (null content)."
      };
      statusLine = null;
      await render();
      return;
    }
    const remote = JSON.parse(remoteJson);
    const rows = diffReports(local, remote);
    compareState = { local, remote, rows, error: null };
    statusLine = `Compared ${rows.length} applet row(s)`;
  } catch (error) {
    compareState = {
      local,
      remote: null,
      rows: [],
      error: error instanceof Error ? error.message : String(error)
    };
    statusLine = null;
  }

  view = "diagnostics";
  await render();
}

function chapterIdFromNode(nodeId) {
  if (nodeId.startsWith("ch-")) {
    return nodeId.slice(3);
  }
  if (nodeId.startsWith("link-")) {
    const rest = nodeId.slice("link-".length);
    let best = null;
    for (const chapter of CATALOG.chapters) {
      const prefix = `${chapter.id}-`;
      if (rest.startsWith(prefix) && (best === null || chapter.id.length > best.length)) {
        best = chapter.id;
      }
    }
    return best;
  }
  return null;
}

function appletIdFromRunNode(nodeId) {
  if (nodeId.startsWith("applet-run-")) {
    return nodeId.slice("applet-run-".length);
  }
  return null;
}

async function handleEvent({ nodeId, event, value }) {
  if (event === "hb.toc") {
    await openToc();
    return;
  }

  if (event === "hb.diagnostics") {
    await openDiagnostics();
    return;
  }

  if (event === "hb.openchapter") {
    const id = chapterIdFromNode(nodeId);
    if (id !== null) {
      await openChapter(id);
    }
    return;
  }

  if (event === "hb.runapplet") {
    const id = appletIdFromRunNode(nodeId);
    if (id !== null) {
      await runAppletInline(id);
    }
    return;
  }

  if (event === "hb.runall") {
    await runAllDiagnostics();
    return;
  }

  if (event === "hb.export") {
    await exportReport();
    return;
  }

  if (event === "hb.compare.input") {
    compareInput = typeof value === "string" ? value : String(value ?? "");
    return;
  }

  if (event === "hb.compare") {
    await compareReport();
  }
}

ui.onEvent((event) => {
  void handleEvent(event).catch(async (error) => {
    statusLine = `Error: ${error instanceof Error ? error.message : String(error)}`;
    await render();
  });
});

await ensureSeeds();

const saved = await kvGetText(POSITION_KEY);
if (saved !== null && findChapter(saved) !== null) {
  chapterId = saved;
  view = "chapter";
} else {
  view = "toc";
}

const cachedReport = await kvGetText(LAST_REPORT_KEY);
if (cachedReport !== null) {
  try {
    compareState = { ...compareState, local: JSON.parse(cachedReport) };
  } catch {
    // ignore corrupt cache
  }
}

await render();
